\label{defn:conc}
Two knots $K_0 \subset \Sigma_0 \times I$ and $K_1 \subset \Sigma_1\times I$ are said to be \textit{concordant} if there exists a compact, oriented 3-manifold $W$ with $\partial W =-\Sigma_0 \cup \Sigma_1$ and an annulus $A$  properly embedded in $W \times I$ such that $\partial A = K_0 \sqcup K_1$. 

More generally, a \textit{cobordism} is an oriented surface $Z$ properly embedded in $W \times I$ such that $\partial Z = K_0 \sqcup K_1$.

\label{remark-tube}
If $L \subset \Sigma \times I$ is a link with spanning surface $F \subset \Sigma \times I$, we can  construct a new surface $F'=F\#_\tau \Sigma$ by connecting $F$ to a parallel copy of $\Sigma$ near $\Sigma \times \{0\}$ by a small thin tube $\tau$.
Notice that if $F'=F\#_\tau \Sigma$, then $e(F')=e(F)$ and $[F'\cup D]=[F\cup D]$ in $H_2(W\times I;{\mathbb Z}/2)$. In particular, if $F\cup D$ satisfies the hypothesis of  \Cref{slice}, then $F'\cup D$ does as well.

\label{determinant}
Let $K \subset \Sigma \times I$ be a knot with spanning surface $F$ such that $e(F)=0$. Suppose further that $K$ is slice. Then  $\det (K,F)$ is
a perfect square.

Choose a slice disk $D\subset W\times I$ as in the proof of \Cref{slice}.
Let $\{\gamma_1, \ldots, \gamma_{2g}\}$ be a basis for $H_1(F; {\mathbb Z})$, obtained by \Cref{kernel}. Then by \Cref{slice}, the matrix of $\mathcal G_{F}$ with respect to this basis has the form
$\begin{bmatrix} 0&A \\ A^\mathsf{T} & B  \end{bmatrix}$, where $A,B$ are $g\times g$ matrices. Then
\begin{equation*}
\begin{split}
\begin{bmatrix} I& 0 \\ -A^\mathsf{T} & xI  \end{bmatrix}
\begin{bmatrix} xI& A \\ A^\mathsf{T} & B  \end{bmatrix}&=
\begin{bmatrix} xI& A \\ 0 & -A^\mathsf{T} A+xB  \end{bmatrix},\\
x^g \det \begin{bmatrix} xI& A \\ A^\mathsf{T} & B  \end{bmatrix}&=
x^g \det (-A^\mathsf{T} A+xB).
\end{split}
\end{equation*}
We divide both sides by $x^g$, and in the remaining equation put $x=0$, it follows that
$$\det \begin{bmatrix} 0&A \\ A^\mathsf{T} & B  \end{bmatrix}=(-1)^g(\det A)^2,$$
therefore, $\det (K,F)$ is a perfect square.

\label{thm-sign}
Let $K \subset \Sigma \times I$ be a  knot with spanning surface $F$  such that $e(F)=0$. Suppose further that $S \subset W \times I$ is an orientable surface with genus $g(S)$  and boundary $\partial S=K$. Assume that the closed surface $E= F \cup S$ satisfies $[E]=0$ in $H_2(W\times I; {\mathbb Z}/2).$  Then $$|\sigma(K,F)| \leq 2g(S)+n(K,F).$$ 
In particular, if $n(K,F)=0$, then $\sigma(K,F)\leq 2 g(S)$.

\label{defn:123}
Let $D$ be a link diagram on $\Sigma$. 
\begin{itemize}
\item[(i)] $D$ is \textit{alternating} if its crossings alternate between over- and under-crossings along every component of $D$, 
\item[(ii)] $D$ is \textit{cellularly embedded} if $\Sigma \smallsetminus D$ is a union of disks, and 
\item[(iii)] $D$ is  \textit{checkerboard colorable} if the regions of $\Sigma \smallsetminus D$ can be colored by two colors so that no two regions sharing an edge have the same color. 
\end{itemize}

If $u'\in U$ is another element with $[u']=[u]$, then $u'=u+2v$ for some $v\in U$. It follows that
\begin{equation*}
\begin{split}
\varphi([u'])&\equiv B(u+2v,u+2v) \text{ (mod $4$)},\\
&=B(u,u)+ B(u,2v)+B(2v,u)+B(2v,2v),\\
               &= B(u,u)+4B(u,v)+ 4B(v,v),\\
               &\equiv \varphi([u]) \text{ (mod $4$)}.
\end{split}
\end{equation*}
This shows that $\varphi$ is well-defined. 

Next, we show that $\varphi$ is a ${\mathbb Z}/4$ quadratic form $(V,\mathpalette\mathbin{\vcenter{\hbox{\scalebox{\,}{$\m@th.55\bullet$}}}})$.
If $[u],[v]\in V$, let $u,v \in U$ be chosen so that they map to $[u],[v]$ under reduction mod 2. Then
\begin{equation*}
\begin{split}
\varphi([u]+[v]) &\equiv B(u+v,u+v) \text{ (mod $4$),}\\
&= B(u,u)+B(v,v) +2B(u,v),\\
&\equiv \varphi([u])+\varphi([v])+2(u\mathpalette\mathbin{\vcenter{\hbox{\scalebox{v}{$\m@th.55\bullet$}}}}) \text{ (mod $4$)}.
\end{split}
\end{equation*}
The claim now follows.

\label{defn:Brown-link}
The Brown invariant of an oriented link $L \subset \Sigma \times I$ with spanning surface $F \subset \Sigma \times I$ is denoted ${\upbeta}_F(L)$ and defined by the formula 
$${\upbeta}_F(L)={\upbeta}(\varphi_F)+\tfrac{1}{2}e(F,L).$$

\label{defn:Brown-link-Goeritz}
The Brown invariant of the oriented checkerboard colorable link diagram $D$ with coloring $\xi$ is given by
$${\upbeta}_{\xi}(D)={\upbeta}(\varphi_{\xi})-\mu_{\xi}(D).$$

\label{prop:mirror_image}
Let $L\subset \Sigma \times I$ be a  link with spanning surface $F \subset \Sigma \times I$.
Then the Brown invariant of the vertical and horizontal mirror images of $L$ satisfy
\begin{eqnarray*}
{\upbeta}_{F^*}(L^*)=-{\upbeta}_{F}(L), \; & \text{and} & \; {\upbeta}_{F^\dag}(L^\dag)=-{\upbeta}_{F}(L). 
\end{eqnarray*}

\label{defn-spanning-surf}
Let $K_0$ and $K_1$ be knots  in $\Sigma_0\times I$ and $\Sigma_1\times I$, respectively, with spanning surfaces $F_0 \subset \Sigma_0 \times I$ and $F_1 \subset \Sigma_1 \times I$.
So $F_0, F_1,$ are unoriented surfaces with boundary $\partial F_0 =K_0$ and $\partial F_1 =K_1$.

The spanning surfaces $F_0$ and $F_1$ are said to be \textit{concordant} if there exist:
\begin{itemize}
\item[(i)] a compact oriented 3-manifold $W$ with boundary $\partial W = -\Sigma_0 \cup \Sigma_1$, 
\item[(ii)] a properly embedded annulus $A \subset W \times I$ with boundary $\partial A = K_0 \cup K_1$, and \item[(iii)] a compact unoriented 3-manifold $V \subset W \times I$ with boundary $\partial V = F_0 \cup A \cup F_1$. 
\end{itemize}

\label{kernel-2}
There are generating sets $\{\gamma_1, \ldots, \gamma_{g_0}\}$ for $H_1(F_0; {\mathbb Z})$ and $\{\gamma'_{1}, \ldots, \gamma'_{g_1}\}$ for $H_1(F_1; {\mathbb Z})$,
such that $\gamma_1, \ldots, \gamma_{m_0},\gamma'_1,\ldots,\gamma'_{m_1}$ lie in the kernel of the map $H_1(F_0;{\mathbb Z})\oplus H_1(F_1;{\mathbb Z}) \to H_1(V;{\mathbb Q}),$ where $m_0+m_1=\frac{1}{2}(g_0+g_1)$.

\label{concordance}
Let $K_0 \subset \Sigma_0\times I$ and $K_1 \subset \Sigma_1\times I$ be knots with spanning surfaces $F_0 \subset \Sigma_0 \times I$ and $F_1 \subset \Sigma_1 \times I$, respectively. If $F_0$ and $F_1$ are concordant and $n(K_0,F_0)=n(K_1,F_1)=0$, then
$$\sigma(K_0,F_0)=\sigma(K_1,F_1).$$

\label{brown-concordance}
Let $K_0 \subset \Sigma_0\times I$ and $K_1 \subset \Sigma_1\times I$ be knots with spanning surfaces $F_0 \subset \Sigma_0 \times I$ and $F_1 \subset \Sigma_1 \times I$, respectively. If $F_0$ and $F_1$ are concordant and $\det(\mathcal G_{F_0}),\det(\mathcal G_{F_1}) \not \equiv 0 \text{ (mod $2$)}$, then
$${\upbeta}_{F_0}(K_0)={\upbeta}_{F_1}(K_1).$$
